term_map = [
('ews','Extreme Wide Shot (EWS)','極遠景','人物相對於環境極小、環境資訊主導的取景尺度。','A framing scale in which the subject is very small relative to the environment.'),('ws','Wide Shot (WS)','遠景','呈現人物全身或大部分身體及周遭空間的取景。','A framing that shows a person’s full or most of their body with surrounding space.'),('fs','Full Shot (FS)','全身景','通常讓人物頭至腳完整入畫；實際邊界依場景與慣例而異。','A framing that generally includes the full body, with conventions varying by context.'),('mls','Medium Long Shot (MLS)','中遠景','人物約膝上或相近範圍的取景；非跨製作通用的硬邊界。','A framing often around the knees upward; boundaries are not universal.'),('ms','Medium Shot (MS)','中景','通常約腰部以上，兼顧表情、手勢與部分環境。','Often frames roughly from the waist up, balancing expression, gesture and context.'),('mcu','Medium Close-Up (MCU)','中近景','多以胸部以上呈現人物表情與有限環境。','Often frames a person from the chest up with limited context.'),('cu','Close-Up (CU)','特寫','使臉部或重要物件成為畫面主要資訊。','A framing that makes a face or important object the primary visual information.'),('ecu','Extreme Close-Up (ECU)','大特寫','只呈現臉或物件很小的局部細節。','Shows only a very small detail of a face or object.'),('ots','Over-the-Shoulder (OTS)','越肩鏡頭','以前景人物肩部或頭部作框景，觀看另一人物或空間。','Frames another person or space past a foreground shoulder or head.'),('pov','Point of View (POV)','主觀視角','將畫面組織為角色所見或感知的視點；需由上下文建立。','Organizes the image as a character’s view or perception, established by context.'),('dolly','Dolly Movement','攝影機前後移動','攝影機機位在空間中前進或後退。','Physical camera translation forward or backward through space.'),('zoom','Zoom','變焦','透過改變焦距改變視角與畫面尺度；攝影機機位可維持不動。','Changes focal length and angle of view, potentially from a fixed camera position.'),('pan','Pan','水平搖攝','攝影機繞固定或近似固定支點水平轉動。','Horizontal rotation of the camera around a fixed or near-fixed position.'),('tilt','Tilt','垂直搖攝','攝影機繞固定或近似固定支點垂直轉動。','Vertical rotation of the camera around a fixed or near-fixed position.'),('truck','Truck Movement','橫向平移','攝影機機位向側方平移，與原地 Pan 不同。','Camera translation sideways, distinct from a pan in place.'),('pedestal','Pedestal','上下平移','攝影機整體垂直升降，不等同 Tilt。','Vertical translation of the whole camera, distinct from a tilt.'),('orbit','Orbit','環繞運鏡','攝影機沿主體周圍弧線改變機位。','Camera position moves along an arc around a subject.'),('rack-focus','Rack Focus','轉焦','在同一鏡頭中把清晰焦點由一距離平面移向另一平面。','Shifts the plane of sharp focus from one distance to another within a shot.'),('depth-of-field','Depth of Field (DoF)','景深','在指定觀看條件下看似可接受清晰的物距範圍。','The range of object distances that appear acceptably sharp under specified viewing conditions.'),('continuity','Continuity','連續性','維持跨鏡頭時間、空間、動作、視線與道具關係可理解的剪輯一致性。','Editorial consistency that keeps temporal, spatial, action, eyeline and prop relations understandable.'),('180-degree-rule','180-Degree Rule','180 度軸線規則','常見連戲慣例：攝影機保持在動作軸線同側以維持螢幕方向；可有意跨越但須重新定位觀眾。','A continuity convention that keeps cameras on one side of an action axis to preserve screen direction; intentional crossings require reorientation.'),('lead-room','Lead Room','前方留白／視線留白','人物注視或移動方向前方保留的畫面空間。','Space left in front of a person in the direction of gaze or movement.'),('headroom','Headroom','頭頂留白','人物頭頂與畫框上緣之間的空間。','Space between the top of a person’s head and the upper frame edge.'),('negative-space','Negative Space','負空間','主體周圍未被主要物件佔據、但具構圖功能的區域。','Areas around the subject not occupied by primary objects but functioning compositionally.'),('focal-length','Focal Length','焦距','鏡頭光學系統的焦距，與感光面尺寸共同關聯視角。','A lens-system parameter that, together with sensor size, relates to angle of view.'),('perspective','Perspective','透視','畫面中空間深度和物體相對大小／位置的投影關係，受攝影機位置影響。','Projected spatial depth and relative size/position relations, affected by camera position.')]
